import pandas as pd
import json
import collections

def parse_volume(v_str):
    if v_str == '<100k': return (0, 100000)
    if v_str == '100k-1m': return (100000, 1000000)
    if v_str == '1m-5m': return (1000000, 5000000)
    if v_str == '>5m': return (5000000, float('inf'))
    return None

def parse_fraud(f_str):
    if f_str == '<7.2%': return (0, 0.072)
    if f_str == '7.2%-7.7%': return (0.072, 0.077)
    if f_str == '7.7%-8.3%': return (0.077, 0.083)
    if f_str == '>8.3%': return (0.083, float('inf'))
    return None

def load_data():
    with open('/data/merchant_data.json', 'r') as f:
        merchants = json.load(f)
    belle = next(m for m in merchants if m['merchant'] == 'Belles_cookbook_store')
    belle_mcc = belle['merchant_category_code']
    belle_account_type = belle['account_type']
    belle_capture_delay_val = belle['capture_delay']

    with open('/data/fees.json', 'r') as f:
        fees = json.load(f)

    return belle, belle_mcc, belle_account_type, belle_capture_delay_val, fees

def parse_capture_delay(val):
    if val == 'immediate': return 'immediate'
    if val == 'manual': return 'manual'
    try:
        days = int(val)
        if days < 3: return '<3'
        if 3 <= days <= 5: return '3-5'
        if days > 5: return '>5'
    except:
        return val
    return val

def main():
    belle, belle_mcc, belle_account_type, belle_capture_delay_val, fees = load_data()
    belle_capture_delay = parse_capture_delay(belle_capture_delay_val)

    # Pre-calculate monthly volume and fraud for Belle in 2023
    monthly_volume = collections.defaultdict(float)
    monthly_fraud_volume = collections.defaultdict(float)

    # We need to map day_of_year to month.
    # 2023 is not a leap year.
    days_in_months = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    month_starts = []
    curr = 1
    for d in days_in_months:
        month_starts.append(curr)
        curr += d

    def get_month(day_of_year):
        for i in range(11, -1, -1):
            if day_of_year >= month_starts[i]:
                return i + 1
        return 1

    print("Calculating monthly metrics...")
    # First pass to get monthly volume and fraud
    for chunk in pd.read_csv('/data/payments.csv', chunksize=100000):
        belle_txs = chunk[(chunk['merchant'] == 'Belles_cookbook_store') & (chunk['year'] == 2023)]
        for _, tx in belle_txs.iterrows():
            m = get_month(tx['day_of_year'])
            monthly_volume[m] += tx['eur_amount']
            if tx['has_fraudulent_dispute']:
                monthly_fraud_volume[m] += tx['eur_amount']

    monthly_fraud_ratio = {}
    for m in range(1, 13):
        if monthly_volume[m] > 0:
            monthly_fraud_ratio[m] = monthly_fraud_volume[m] / monthly_volume[m]
        else:
            monthly_fraud_ratio[m] = 0.0

    print(f"Monthly Volumes: {dict(monthly_volume)}")
    print(f"Monthly Fraud Ratios: {dict(monthly_fraud_ratio)}")

    # Second pass: calculate fees
    total_fees = 0.0

    # Group rules by month for efficiency if they have monthly requirements
    rules_by_month = {}
    for m in range(1, 13):
        vol = monthly_volume[m]
        fraud = monthly_fraud_ratio[m]

        m_rules = []
        for r in fees:
            # Static filters
            if r['account_type'] and belle_account_type not in r['account_type']:
                continue
            if r['merchant_category_code'] and belle_mcc not in r['merchant_category_code']:
                continue
            if r['capture_delay'] is not None and r['capture_delay'] != belle_capture_delay:
                continue

            # Monthly filters
            if r['monthly_volume'] is not None:
                v_range = parse_volume(r['monthly_volume'])
                if not (v_range[0] <= vol < v_range[1]):
                    continue
            if r['monthly_fraud_level'] is not None:
                f_range = parse_fraud(r['monthly_fraud_level'])
                if not (f_range[0] <= fraud < f_range[1]):
                    continue

            m_rules.append(r)
        rules_by_month[m] = m_rules

    print("Calculating fees...")
    for chunk in pd.read_csv('/data/payments.csv', chunksize=100000):
        belle_txs = chunk[(chunk['merchant'] == 'Belles_cookbook_store') & (chunk['year'] == 2023)]
        for _, tx in belle_txs.iterrows():
            m = get_month(tx['day_of_year'])
            tx_fees = 0.0
            is_intra = (tx['issuing_country'] == tx['acquirer_country'])

            for r in rules_by_month[m]:
                if r['card_scheme'] is not None and r['card_scheme'] != tx['card_scheme']:
                    continue
                if r['is_credit'] is not None and r['is_credit'] != tx['is_credit']:
                    continue
                if r['aci'] and tx['aci'] not in r['aci']:
                    continue
                if r['intracountry'] is not None and r['intracountry'] != is_intra:
                    continue

                tx_fees += r['fixed_amount'] + (r['rate'] * tx['eur_amount'] / 10000.0)

            total_fees += tx_fees

    print(f"Total Fees: {total_fees:.4f}")
    with open('/output/answer.txt', 'w') as f:
        f.write(f"{total_fees:.4f}")

if __name__ == "__main__":
    main()
